// SRP: Separate responsibilities
public class User { /* User data */ }
public class UserRepository { /* Data access */ }
public class EmailService { /* Email logic */ }

// OCP: Open for extension
public interface IPaymentProcessor {
    void ProcessPayment(decimal amount);
}
public class CreditCardProcessor : IPaymentProcessor { }
public class PayPalProcessor : IPaymentProcessor { }
// Add new payment method without changing existing code

// LSP: Substitutability
public class Bird { public virtual void Fly() { } }
public class Sparrow : Bird { }
// BAD: public class Ostrich : Bird { public override void Fly() { throw new Exception(); } }
// GOOD: Separate flying and non-flying birds

// ISP: Small interfaces
public interface IReadable { string Read(); }
public interface IWritable { void Write(string text); }
// Instead of one large IStorage interface

// DIP: Depend on abstractions
public interface INotificationService {
    void Send(string message);
}
public class NotificationController {
    private readonly INotificationService _notificationService;
    // Depends on interface, not concrete implementation
}
